import { AlertTriangle, GitBranch, Trash2, X } from "lucide-react";
import { useEffect, useMemo, useState } from "react";

import {
  DEFAULT_WORKSPACE_ID,
  deleteWorktree,
  deleteWorktreeDestructive,
  previewWorktreeDelete,
  toIpcError,
} from "../lib/tauri";
import { worktreeIdentity, type BranchDeletionPreview, type StructuredIpcError, type Worktree } from "../lib/types";

export type WorktreeDeleteServices = {
  previewDelete: (worktree: Worktree) => Promise<BranchDeletionPreview>;
  deleteSafe: (worktree: Worktree) => Promise<void>;
  deleteDestructive: (worktree: Worktree) => Promise<void>;
};

type WorktreeDeleteDialogProps = {
  workspaceId?: string;
  worktree: Worktree;
  onClose: () => void;
  onDeleted: () => void;
  services?: WorktreeDeleteServices;
};

function createDefaultServices(workspaceId: string): WorktreeDeleteServices {
  return {
    previewDelete: async (worktree) => {
      const identity = requireIdentity(worktree);
      return previewWorktreeDelete({ workspaceId, worktree: identity });
    },
    deleteSafe: async (worktree) => {
      const identity = requireIdentity(worktree);
      await deleteWorktree({ workspaceId, worktree: identity, deleteBranch: true });
    },
    deleteDestructive: async (worktree) => {
      const identity = requireIdentity(worktree);
      await deleteWorktreeDestructive({ workspaceId, worktree: identity, deleteBranch: true });
    },
  };
}

export function WorktreeDeleteDialog({
  workspaceId = DEFAULT_WORKSPACE_ID,
  worktree,
  onClose,
  onDeleted,
  services,
}: WorktreeDeleteDialogProps) {
  const resolvedServices = useMemo(() => services ?? createDefaultServices(workspaceId), [services, workspaceId]);
  const [preview, setPreview] = useState<BranchDeletionPreview | null>(null);
  const [error, setError] = useState<StructuredIpcError | null>(null);
  const [destructiveRequired, setDestructiveRequired] = useState(false);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    let cancelled = false;
    setPreview(null);
    setError(null);
    setDestructiveRequired(false);
    setBusy(true);
    void resolvedServices
      .previewDelete(worktree)
      .then((result) => {
        if (!cancelled) setPreview(result);
      })
      .catch((cause) => {
        if (!cancelled) setError(toIpcError(cause));
      })
      .finally(() => {
        if (!cancelled) setBusy(false);
      });
    return () => {
      cancelled = true;
    };
  }, [resolvedServices, worktree]);

  const finishDelete = () => {
    onDeleted();
    onClose();
  };

  const handleSafeDelete = async () => {
    setBusy(true);
    setError(null);
    try {
      await resolvedServices.deleteSafe(worktree);
      finishDelete();
    } catch (cause) {
      const ipcError = toIpcError(cause);
      setError(ipcError);
      setDestructiveRequired(ipcError.code === "UNMERGED_BRANCH");
    } finally {
      setBusy(false);
    }
  };

  const handleDestructiveDelete = async () => {
    setBusy(true);
    setError(null);
    try {
      await resolvedServices.deleteDestructive(worktree);
      finishDelete();
    } catch (cause) {
      setError(toIpcError(cause));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm" onMouseDown={onClose}>
      <div
        role="dialog"
        aria-label="Delete worktree"
        aria-modal="true"
        className="w-full max-w-lg animate-enter overflow-hidden rounded-xl border border-border bg-card shadow-2xl"
        onMouseDown={(event) => event.stopPropagation()}
      >
        <header className="flex items-center justify-between border-b border-border px-4 py-3">
          <div className="flex items-center gap-2 text-sm font-semibold text-foreground">
            <Trash2 className="size-4 text-destructive" />
            Delete worktree
          </div>
          <button type="button" onClick={onClose} aria-label="Close delete dialog" className="rounded-md p-1 text-muted-foreground hover:bg-accent hover:text-foreground">
            <X className="size-4" />
          </button>
        </header>

        <div className="space-y-4 p-4 text-xs">
          <p className="text-muted-foreground">Review the branch state before deleting this worktree.</p>
          <div data-testid="worktree-delete-path" className="break-all rounded-md border border-border bg-muted/40 px-3 py-2 font-mono text-foreground">
            {worktree.path}
          </div>

          {busy && !preview ? <div className="rounded-md border border-border bg-background/50 px-3 py-4 text-muted-foreground">Loading deletion preview…</div> : null}

          {preview ? (
            <div className="overflow-hidden rounded-lg border border-border bg-background/45">
              <PreviewRow label="Branch" value={preview.branch} icon={<GitBranch className="size-3" />} />
              <PreviewRow label="HEAD" value={preview.head} mono />
              <PreviewRow label="Upstream" value={preview.upstream ?? "None"} />
              <PreviewRow label="Merge state" value={preview.merged ? "Merged" : "Not merged"} />
              <PreviewRow
                label="Divergence"
                value={preview.upstream === null ? "No upstream" : `${preview.ahead ?? "—"} ahead · ${preview.behind ?? "—"} behind`}
                dataState={preview.upstream === null ? "no-upstream" : "upstream"}
              />
            </div>
          ) : null}

          {destructiveRequired ? (
            <div className="space-y-2 rounded-lg border border-destructive/35 bg-destructive/10 p-3">
              <div className="flex items-start gap-2 text-destructive">
                <AlertTriangle className="mt-0.5 size-4 shrink-0" />
                <div>
                  <div className="font-semibold">Unmerged branch</div>
                  <p className="mt-1 text-[11px] leading-relaxed text-destructive/85">
                    Safe deletion refused to discard unmerged commits. Destructive deletion is a separate explicit action.
                  </p>
                </div>
              </div>
              <button
                type="button"
                disabled={busy}
                onClick={() => void handleDestructiveDelete()}
                className="w-full rounded-md bg-destructive px-3 py-2 font-semibold text-destructive-foreground disabled:opacity-50"
              >
                Delete unmerged branch permanently
              </button>
            </div>
          ) : null}

          {error && !destructiveRequired ? (
            <div className="rounded-md border border-destructive/30 bg-destructive/10 px-3 py-2 text-destructive">
              <div className="font-semibold">{error.code}</div>
              <div className="mt-0.5 text-[11px]">{error.message}</div>
            </div>
          ) : null}

          <div className="flex justify-end gap-2">
            <button type="button" onClick={onClose} className="rounded-md px-3 py-2 text-muted-foreground hover:bg-accent hover:text-foreground">
              Cancel
            </button>
            {!destructiveRequired ? (
              <button
                type="button"
                disabled={busy || !preview}
                onClick={() => void handleSafeDelete()}
                className="rounded-md bg-destructive px-3 py-2 font-semibold text-destructive-foreground disabled:opacity-50"
              >
                Delete worktree and branch
              </button>
            ) : null}
          </div>
        </div>
      </div>
    </div>
  );
}

function PreviewRow({ label, value, mono = false, icon, dataState }: { label: string; value: string; mono?: boolean; icon?: React.ReactNode; dataState?: string }) {
  return (
    <div data-testid={dataState ? "worktree-delete-divergence" : undefined} data-state={dataState} className="flex items-center gap-3 border-b border-border px-3 py-2 last:border-b-0">
      <span className="flex w-24 shrink-0 items-center gap-1 text-muted-foreground">{icon}{label}</span>
      <span className={`min-w-0 flex-1 truncate text-right text-foreground ${mono ? "font-mono" : ""}`}>{value}</span>
    </div>
  );
}

function requireIdentity(worktree: Worktree) {
  const identity = worktreeIdentity(worktree);
  if (identity) return identity;
  throw {
    code: "INVALID_NAMESPACE",
    message: "Only Ferryx-managed worktrees can be deleted from this UI.",
    details: { path: worktree.path },
  } satisfies StructuredIpcError;
}

import { cleanup, fireEvent, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import type { Worktree } from "../lib/types";
import { WorktreeDeleteDialog, type WorktreeDeleteServices } from "./WorktreeDeleteDialog";

const native = vi.hoisted(() => ({
  previewWorktreeDelete: vi.fn(),
  deleteWorktree: vi.fn(),
  deleteWorktreeDestructive: vi.fn(),
}));

vi.mock("../lib/tauri", async (importOriginal) => {
  const actual = await importOriginal<typeof import("../lib/tauri")>();
  return {
    ...actual,
    previewWorktreeDelete: native.previewWorktreeDelete,
    deleteWorktree: native.deleteWorktree,
    deleteWorktreeDestructive: native.deleteWorktreeDestructive,
  };
});

const worktree: Worktree = {
  path: "/repo/feature",
  head: "abc123",
  branch: "refs/heads/orca/ws-main/feature",
  bare: false,
  detached: false,
  locked: null,
  prunable: null,
};

const preview = {
  branch: "orca/ws-main/feature",
  head: "abc123def456",
  upstream: "origin/orca/ws-main/feature",
  merged: false,
  ahead: 2,
  behind: 1,
};

function createServices(overrides: Partial<WorktreeDeleteServices> = {}): WorktreeDeleteServices {
  return {
    previewDelete: vi.fn(async () => preview),
    deleteSafe: vi.fn(async () => undefined),
    deleteDestructive: vi.fn(async () => undefined),
    ...overrides,
  };
}

beforeEach(() => {
  native.previewWorktreeDelete.mockReset();
  native.deleteWorktree.mockReset();
  native.deleteWorktreeDestructive.mockReset();
  native.previewWorktreeDelete.mockResolvedValue(preview);
  native.deleteWorktree.mockResolvedValue(undefined);
  native.deleteWorktreeDestructive.mockResolvedValue(undefined);
});
afterEach(cleanup);

describe("WorktreeDeleteDialog", () => {
  it("shows branch safety metadata before safe deletion", async () => {
    const services = createServices();
    const onDeleted = vi.fn();
    render(<WorktreeDeleteDialog worktree={worktree} services={services} onClose={vi.fn()} onDeleted={onDeleted} />);

    expect(await screen.findByText("orca/ws-main/feature")).toBeInTheDocument();
    expect(screen.getByText("abc123def456")).toBeInTheDocument();
    expect(screen.getByText("origin/orca/ws-main/feature")).toBeInTheDocument();
    expect(screen.getByText(/not merged/i)).toBeInTheDocument();
    expect(screen.getByText(/2 ahead/i)).toBeInTheDocument();
    expect(screen.getByText(/1 behind/i)).toBeInTheDocument();
    expect(screen.getByTestId("worktree-delete-divergence")).toHaveAttribute("data-state", "upstream");

    fireEvent.click(screen.getByRole("button", { name: "Delete worktree and branch" }));
    await waitFor(() => expect(services.deleteSafe).toHaveBeenCalledWith(worktree));
    expect(onDeleted).toHaveBeenCalledOnce();
  });

  it("contains an absolute hyphenated path and shows an explicit no-upstream divergence state", async () => {
    const selectedWorktree = { ...worktree, path: "/repo/worktrees/orca-ws-main/task-ipc-branch" };
    const services = createServices({
      previewDelete: vi.fn(async () => ({ ...preview, upstream: null, ahead: null, behind: null })),
    });
    render(<WorktreeDeleteDialog worktree={selectedWorktree} services={services} onClose={vi.fn()} onDeleted={vi.fn()} />);

    const path = await screen.findByTestId("worktree-delete-path");
    expect(path).toHaveTextContent(selectedWorktree.path);
    expect(path).toHaveClass("break-all");
    expect(screen.queryByText(/\? ahead · \? behind/)).not.toBeInTheDocument();
    expect(screen.getByTestId("worktree-delete-divergence")).toHaveAttribute("data-state", "no-upstream");
  });

  it("scopes native preview and safe deletion to the selected registered workspace", async () => {
    render(
      <WorktreeDeleteDialog
        {...({ workspaceId: "project-a", worktree, onClose: vi.fn(), onDeleted: vi.fn() } as any)}
      />,
    );

    await screen.findByText("orca/ws-main/feature");
    expect(native.previewWorktreeDelete).toHaveBeenCalledWith({
      workspaceId: "project-a",
      worktree: { wsId: "ws-main", slug: "feature" },
    });

    fireEvent.click(screen.getByRole("button", { name: "Delete worktree and branch" }));
    await waitFor(() => expect(native.deleteWorktree).toHaveBeenCalledWith({
      workspaceId: "project-a",
      worktree: { wsId: "ws-main", slug: "feature" },
      deleteBranch: true,
    }));
  });

  it("offers destructive deletion only for the UNMERGED_BRANCH error code", async () => {
    const services = createServices({
      deleteSafe: vi.fn(async () => {
        throw { code: "UNMERGED_BRANCH", message: "opaque backend wording", details: {} };
      }),
    });
    render(<WorktreeDeleteDialog worktree={worktree} services={services} onClose={vi.fn()} onDeleted={vi.fn()} />);

    await screen.findByText("orca/ws-main/feature");
    fireEvent.click(screen.getByRole("button", { name: "Delete worktree and branch" }));
    expect(await screen.findByRole("button", { name: "Delete unmerged branch permanently" })).toBeInTheDocument();

    fireEvent.click(screen.getByRole("button", { name: "Delete unmerged branch permanently" }));
    await waitFor(() => expect(services.deleteDestructive).toHaveBeenCalledWith(worktree));
  });

  it("does not infer destructive deletion from an error message", async () => {
    const services = createServices({
      deleteSafe: vi.fn(async () => {
        throw { code: "GIT_ERROR", message: "unmerged branch text must not drive UI", details: {} };
      }),
    });
    render(<WorktreeDeleteDialog worktree={worktree} services={services} onClose={vi.fn()} onDeleted={vi.fn()} />);

    await screen.findByText("orca/ws-main/feature");
    fireEvent.click(screen.getByRole("button", { name: "Delete worktree and branch" }));
    await screen.findByText("GIT_ERROR");
    expect(screen.queryByRole("button", { name: "Delete unmerged branch permanently" })).not.toBeInTheDocument();
  });
});

use crate::ipc::*;
use crate::terminal::TerminalService;
use crate::worktree::{run_git, WorkspaceRegistry, WorktreeIdentity};
use base64::{engine::general_purpose::STANDARD, Engine as _};
use std::sync::Arc;
use tauri::{Listener, Manager};
use tempfile::TempDir;


fn setup_workspace() -> (TempDir, WorkspaceRegistry) {
    let repo = TempDir::new().expect("repo tempdir");
    run_git(repo.path(), &["init"]).expect("git init");
    run_git(repo.path(), &["config", "user.email", "test@example.com"]).expect("email");
    run_git(repo.path(), &["config", "user.name", "Test User"]).expect("name");
    std::fs::write(repo.path().join("README.md"), "initial\n").expect("README");
    run_git(repo.path(), &["add", "README.md"]).expect("add");
    run_git(repo.path(), &["commit", "-m", "initial commit"]).expect("commit");

    let registry = WorkspaceRegistry::new();
    registry.register("workspace-test", repo.path()).expect("register");
    (repo, registry)
}

#[tokio::test]
async fn tauri_mock_terminal_events_use_registered_workspace() {
    let (_repo, registry) = setup_workspace();
    let app = tauri::test::mock_builder()
        .manage(Arc::new(TerminalService::default()))
        .manage(registry)
        .build(tauri::test::mock_context(tauri::test::noop_assets()))
        .expect("mock app");

    let terminal_service = app.state::<Arc<TerminalService>>();
    let registry_state = app.state::<WorkspaceRegistry>();
    let (tx, mut rx_event) = tokio::sync::mpsc::channel::<TerminalOutputPayload>(16);
    app.listen(TERMINAL_OUTPUT_EVENT, move |event: tauri::Event| {
        if let Ok(payload) = serde_json::from_str::<TerminalOutputPayload>(event.payload()) {
            let _ = tx.try_send(payload);
        }
    });

    let spawned = cmd_terminal_spawn(
        app.handle().clone(),
        terminal_service.clone(),
        registry_state,
        SpawnTerminalRequest {
            workspace_id: "workspace-test".into(),
            worktree: None,
            cwd: None,
            cols: Some(80),
            rows: Some(24),
        },
    )
    .await
    .expect("spawn");

    cmd_terminal_write(
        terminal_service.clone(),
        spawned.session_id.clone(),
        "echo hello_orca_terminal\n".into(),
    )
    .await
    .expect("write");

    let mut collected = Vec::new();
    tokio::time::timeout(tokio::time::Duration::from_secs(5), async {
        while !String::from_utf8_lossy(&collected).contains("hello_orca_terminal") {
            let payload = rx_event.recv().await.expect("terminal output");
            assert_eq!(payload.session_id, spawned.session_id);
            collected.extend_from_slice(&STANDARD.decode(payload.data).expect("base64"));
        }
    })
    .await
    .expect("terminal output timeout");

    cmd_terminal_resize(
        terminal_service.clone(),
        spawned.session_id.clone(),
        120,
        40,
    )
    .await
    .expect("resize");
    let sessions = cmd_terminal_list(terminal_service.clone()).await.expect("list");
    assert!(sessions
        .iter()
        .any(|session| session.session_id == spawned.session_id));

    cmd_terminal_close(terminal_service.clone(), spawned.session_id.clone())
        .await
        .expect("close");
    cmd_terminal_close(terminal_service.clone(), spawned.session_id.clone())
        .await
        .expect("idempotent close");
    let sessions = cmd_terminal_list(terminal_service).await.expect("list after");
    assert!(!sessions
        .iter()
        .any(|session| session.session_id == spawned.session_id));
}

#[tokio::test]
async fn tauri_mock_worktree_commands_use_identity_contract() {
    let (repo, registry) = setup_workspace();
    let app = tauri::test::mock_builder()
        .manage(Arc::new(TerminalService::default()))
        .manage(registry)
        .build(tauri::test::mock_context(tauri::test::noop_assets()))
        .expect("mock app");
    let registry_state = app.state::<WorkspaceRegistry>();
    let identity = WorktreeIdentity {
        ws_id: "ws-ipc".into(),
        slug: "task-ipc".into(),
    };

    let initial = cmd_worktree_list(registry_state.clone(), "workspace-test".into())
        .await
        .expect("initial list");
    assert_eq!(initial.len(), 1);

    let created = cmd_worktree_create(
        app.handle().clone(),
        registry_state.clone(),
        CreateWorktreeRequest {
            workspace_id: "workspace-test".into(),
            worktree: identity.clone(),
            base_ref: None,
        },
    )
    .await
    .expect("create");
    assert!(created.path.exists());

    let status = cmd_worktree_status(
        app.handle().clone(),
        registry_state.clone(),
        WorktreeStatusRequest {
            workspace_id: "workspace-test".into(),
            worktree: identity.clone(),
        },
    )
    .await
    .expect("status");
    assert!(!status.is_dirty);

    cmd_worktree_delete(
        app.handle().clone(),
        registry_state.clone(),
        DeleteWorktreeRequest {
            workspace_id: "workspace-test".into(),
            worktree: identity.clone(),
            delete_branch: Some(true),
        },
    )
    .await
    .expect("delete");

    assert!(!created.path.exists());
    let branches = run_git(repo.path(), &["branch", "--list"]).expect("list branches");
    assert!(!branches.contains("orca/ws-ipc/task-ipc"));

    let final_list = cmd_worktree_list(registry_state, "workspace-test".into())
        .await
        .expect("final list");
    assert_eq!(final_list.len(), 1);
}

#[tokio::test]
async fn terminal_global_events_preserve_raw_bytes_and_lifecycle() {
    let (_repo, registry) = setup_workspace();
    let app = tauri::test::mock_builder()
        .manage(Arc::new(TerminalService::default()))
        .manage(registry)
        .build(tauri::test::mock_context(tauri::test::noop_assets()))
        .expect("mock app");

    let terminal_service = app.state::<Arc<TerminalService>>();
    let registry_state = app.state::<WorkspaceRegistry>();
    let (output_tx, mut output_rx) = tokio::sync::mpsc::channel::<TerminalOutputPayload>(32);
    let (lifecycle_tx, mut lifecycle_rx) =
        tokio::sync::mpsc::channel::<TerminalLifecyclePayload>(8);

    app.listen(TERMINAL_OUTPUT_EVENT, move |event: tauri::Event| {
        if let Ok(payload) = serde_json::from_str::<TerminalOutputPayload>(event.payload()) {
            let _ = output_tx.try_send(payload);
        }
    });
    app.listen(TERMINAL_LIFECYCLE_EVENT, move |event: tauri::Event| {
        if let Ok(payload) = serde_json::from_str::<TerminalLifecyclePayload>(event.payload()) {
            let _ = lifecycle_tx.try_send(payload);
        }
    });

    let spawned = cmd_terminal_spawn(
        app.handle().clone(),
        terminal_service.clone(),
        registry_state,
        SpawnTerminalRequest {
            workspace_id: "workspace-test".into(),
            worktree: None,
            cwd: None,
            cols: Some(80),
            rows: Some(24),
        },
    )
    .await
    .expect("spawn");

    let started = tokio::time::timeout(tokio::time::Duration::from_secs(2), lifecycle_rx.recv())
        .await
        .expect("started timeout")
        .expect("started event");
    assert_eq!(started.session_id, spawned.session_id);
    assert_eq!(started.state, TerminalLifecycleState::Started);

    cmd_terminal_write(
        terminal_service.clone(),
        spawned.session_id.clone(),
        "printf '\\377\\376\\n'\n".into(),
    )
    .await
    .expect("write raw bytes");

    let mut raw = Vec::new();
    tokio::time::timeout(tokio::time::Duration::from_secs(5), async {
        while !raw.windows(2).any(|window| window == [0xff, 0xfe]) {
            let payload = output_rx.recv().await.expect("output event");
            assert_eq!(payload.session_id, spawned.session_id);
            raw.extend_from_slice(&STANDARD.decode(payload.data).expect("base64 payload"));
        }
    })
    .await
    .expect("raw output timeout");

    cmd_terminal_close(terminal_service, spawned.session_id.clone())
        .await
        .expect("close");

    let exited = tokio::time::timeout(tokio::time::Duration::from_secs(2), lifecycle_rx.recv())
        .await
        .expect("exited timeout")
        .expect("exited event");
    assert_eq!(exited.session_id, spawned.session_id);
    assert_eq!(exited.state, TerminalLifecycleState::Exited);
    assert!(exited.reason.is_none());
}

#[tokio::test]
async fn terminal_cwd_cache_and_resolution_contract() {
    let (_repo, registry) = setup_workspace();
    let app = tauri::test::mock_builder()
        .manage(Arc::new(TerminalService::default()))
        .manage(registry)
        .build(tauri::test::mock_context(tauri::test::noop_assets()))
        .expect("mock app");

    let terminal_service = app.state::<Arc<TerminalService>>();
    let registry_state = app.state::<WorkspaceRegistry>();

    let spawned = cmd_terminal_spawn(
        app.handle().clone(),
        terminal_service.clone(),
        registry_state,
        SpawnTerminalRequest {
            workspace_id: "workspace-test".into(),
            worktree: None,
            cwd: None,
            cols: Some(80),
            rows: Some(24),
        },
    )
    .await
    .expect("spawn");

    let cwd_res = cmd_terminal_get_cwd(terminal_service.clone(), spawned.session_id.clone())
        .await
        .expect("get cwd");
    assert!(cwd_res.cwd.exists());

    let cached = get_cached_cwd(&spawned.session_id);
    assert_eq!(cached, Some(cwd_res.cwd.clone()));

    cmd_terminal_close(terminal_service.clone(), spawned.session_id.clone())
        .await
        .expect("close");
    assert_eq!(get_cached_cwd(&spawned.session_id), None);
}

#[tokio::test]
async fn terminal_output_batching_coalesces_rapid_bursts() {
    let (_repo, registry) = setup_workspace();
    let app = tauri::test::mock_builder()
        .manage(Arc::new(TerminalService::default()))
        .manage(registry)
        .build(tauri::test::mock_context(tauri::test::noop_assets()))
        .expect("mock app");

    let terminal_service = app.state::<Arc<TerminalService>>();
    let registry_state = app.state::<WorkspaceRegistry>();
    let (output_tx, mut output_rx) = tokio::sync::mpsc::channel::<TerminalOutputPayload>(100);

    app.listen(TERMINAL_OUTPUT_EVENT, move |event: tauri::Event| {
        if let Ok(payload) = serde_json::from_str::<TerminalOutputPayload>(event.payload()) {
            let _ = output_tx.try_send(payload);
        }
    });

    let spawned = cmd_terminal_spawn(
        app.handle().clone(),
        terminal_service.clone(),
        registry_state,
        SpawnTerminalRequest {
            workspace_id: "workspace-test".into(),
            worktree: None,
            cwd: None,
            cols: Some(80),
            rows: Some(24),
        },
    )
    .await
    .expect("spawn");

    cmd_terminal_write(
        terminal_service.clone(),
        spawned.session_id.clone(),
        "for i in $(seq 1 20); do echo \"LINE_$i\"; done\n".into(),
    )
    .await
    .expect("write burst");

    let mut event_count = 0;
    let mut collected = Vec::new();
    tokio::time::timeout(tokio::time::Duration::from_secs(5), async {
        while !String::from_utf8_lossy(&collected).contains("LINE_20") {
            let payload = output_rx.recv().await.expect("output event");
            assert_eq!(payload.session_id, spawned.session_id);
            event_count += 1;
            collected.extend_from_slice(&STANDARD.decode(payload.data).expect("base64 payload"));
        }
    })
    .await
    .expect("burst output timeout");

    let output_str = String::from_utf8_lossy(&collected);
    assert!(output_str.contains("LINE_1"));
    assert!(output_str.contains("LINE_20"));
    assert!(event_count < 15, "expected batched events < 15, got {event_count}");

    cmd_terminal_close(terminal_service, spawned.session_id).await.expect("close");
}

#[test]
fn terminal_process_cwd_resolves_accurately() {
    let current_pid = std::process::id();
    let resolved = process_cwd(current_pid);
    assert!(resolved.is_some(), "process_cwd should resolve current pid");
    let resolved_path = resolved.expect("resolved path");
    assert!(resolved_path.exists());
    let current_dir = std::env::current_dir().expect("current dir");
    assert_eq!(
        resolved_path.canonicalize().expect("canonicalize resolved"),
        current_dir.canonicalize().expect("canonicalize current dir")
    );
}

